import type { ReactElement } from "react";
import { UsageMeter } from "./usage-meter";

export type UsagePanelProps = { summary: BillingSummary };

/** Human labels for the quota dimensions, in the order the panel shows them. */
export const RESOURCE_LABELS: Readonly<Record<LimitedResource, string>> = {
  seats: "Seats",
  projects: "Projects",
  issuesPerProject: "Issues per project",
  storageMb: "Storage (MB)",
  apiRequestsPerHour: "API requests / hour",
  webhooks: "Webhooks",
};

const RESOURCE_ORDER: readonly LimitedResource[] = [
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
];

export function UsagePanel(props: UsagePanelProps): ReactElement | null {
  const { summary } = props;
  // The subscription says which plan; the plan table says what it includes.
  const limits = getPlanLimits(summary.subscription.plan);

  const byResource = new Map(
    summary.checks.map((check) => [check.resource, check]),

export const limitedResourceSchema = z.enum([
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
]);

export const changePlanSchema = z.object({
  orgId: orgIdSchema,
  plan: planIdSchema,
  interval: billingIntervalSchema.default("monthly"),
});

export const updateSeatsSchema = z.object({
  orgId: orgIdSchema,
  seats: z.number().int().min(1).max(10_000),
});

export const cancelSubscriptionSchema = z.object({
  orgId: orgIdSchema,
  reason: z.string().max(500).optional(),
  cancelImmediately: z.boolean().default(false),
});
import { RESOURCE_LABELS } from "./usage-panel";

export type PlanComparisonTableProps = {
  currentPlan: PlanId;
  onSelect: (plan: PlanId) => void;
};

const ROWS: readonly LimitedResource[] = [
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
];

export function PlanComparisonTable(
  props: PlanComparisonTableProps,
): ReactElement | null {
  const { currentPlan, onSelect } = props;
  // Every number below comes from the plan table — the marketing page and the
  // billing settings page cannot disagree because neither one owns a literal.
  const plans = PLAN_IDS.map((plan) => getPlanLimits(plan));

  return (
    <Table caption="Plan comparison">
      <TableHead>
        <TableRow>
          <TableHeaderCell></TableHeaderCell>
          {plans.map((limits) => (
            <TableHeaderCell key={limits.plan}>
              {limits.plan}
              {limits.plan === currentPlan ? (
                <Badge tone="brand" size="sm">
                  Current
                </Badge>
              ) : null}
            </TableHeaderCell>
          ))}
        </TableRow>
      </TableHead>

      <TableBody>
        <TableRow>
          <TableCell>Price per seat</TableCell>
          {plans.map((limits) => (
            <TableCell key={limits.plan}>
              {formatCents(limits.priceCentsPerSeatMonthly)}
            </TableCell>
          ))}
        </TableRow>

