/**
 * Calendar-day arithmetic for recurring issues.
 *
 * Occurrences are plain `YYYY-MM-DD` days in a rule's own IANA time zone, so
 * nothing here deals in instants except `localDateIn()`, which asks the
 * runtime's time-zone database (daylight-saving rules included) what day it
 * is in that zone at a given moment. Everything else is pure date math done
 * on UTC midnights, where every day is exactly 24 hours long.
 */
import type { RecurrenceCadence } from "@/types/recurring-issue";

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** The fields of a rule that decide when it occurs. */
export interface RecurrenceSpec {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
}

/**
 * True for a zone name the runtime's time-zone database knows. Offset
 * strings such as `+05:00` are accepted by `Intl` but are not IANA zones.
 */
export function isIanaTimeZone(value: string): boolean {
  if (!/^[A-Za-z]/.test(value)) return false;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

/** True for a `YYYY-MM-DD` string naming a real day (`2026-02-30` is not). */
export function isCalendarDate(value: string): boolean {
  const match = DATE_PATTERN.exec(value);
  if (!match) return false;

  const [, year, month, day] = match.map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCFullYear(year);

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** The calendar day it is in `timezone` at `instant`, as `YYYY-MM-DD`. */
export function localDateIn(timezone: string, instant: Date): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    calendar: "gregory",
    numberingSystem: "latn",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  const part = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((entry) => entry.type === type)?.value ?? "";

  return `${part("year").padStart(4, "0")}-${part("month")}-${part("day")}`;
}

/** ISO weekday of a `YYYY-MM-DD` day: 1 = Monday … 7 = Sunday. */
export function isoWeekday(date: string): number {
  const day = toUtcMidnight(date).getUTCDay();
  return day === 0 ? 7 : day;
}

/** `date` shifted by `days` calendar days. */
export function addCalendarDays(date: string, days: number): string {
  const shifted = new Date(toUtcMidnight(date).getTime() + days * MS_PER_DAY);
  return shifted.toISOString().slice(0, 10);
}

/**
 * The latest occurrence day that has started by `now`, or `null` when none
 * has. Day D has started once the local time in the rule's zone has reached
 * 00:00 on D — i.e. once the local calendar date is D or later.
 */
export function latestStartedOccurrence(
  spec: RecurrenceSpec,
  now: Date,
): string | null {
  const today = localDateIn(spec.timezone, now);
  if (today < spec.startsOn) return null;

  if (spec.cadence === "daily") return today;

  if (spec.weekday === null) return null;
  const back = (isoWeekday(today) - spec.weekday + 7) % 7;
  const latest = addCalendarDays(today, -back);

  return latest < spec.startsOn ? null : latest;
}

function toUtcMidnight(date: string): Date {
  const match = DATE_PATTERN.exec(date);
  if (!match) throw new RangeError(`Malformed calendar date: "${date}"`);

  const [, year, month, day] = match.map(Number);
  const midnight = new Date(Date.UTC(year, month - 1, day));
  midnight.setUTCFullYear(year);
  return midnight;
}

