/**
 * Files the latest due occurrence of every non-paused recurring-issue rule as an ordinary issue.
 *
 * Must call (do not reimplement): can, isArchived, createIssue, resolveActor
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { latestStartedOccurrence } from "@/lib/recurrence";
import { isArchived } from "@/lib/soft-delete";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource, requireFound } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import { resolveActor } from "@/server/services/member-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/** What one rule's pass came to. */
type Outcome = "created" | "not_due" | "skipped" | "paused";

/**
 * One pass over every rule. Missed occurrences are never back-filled: a rule
 * files at most one issue per run, always for its latest started occurrence,
 * and `lastOccurrenceOn` is what makes a second run for the same `now` a
 * no-op. A rule whose issue is refused is left exactly as it was, so a later
 * run tries again; one rule's failure never stops the others.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        const outcome = await fileLatestOccurrence(rule, now);
        if (outcome === "created") result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue not filed", {
          orgId: rule.orgId,
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function fileLatestOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<Outcome> {
  const occurrence = latestStartedOccurrence(rule, now);
  if (occurrence === null) return "not_due";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "not_due";
  }

  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  // Left untouched: once the project is restored, the next run files the
  // then-latest occurrence.
  if (isArchived(project)) return "skipped";

  // Filed on behalf of the rule's creator, with their current role — a
  // creator who left or lost `issue:create` stops the rule rather than
  // failing it on every pass.
  const creator = await resolveActor(rule.createdBy, rule.orgId);
  if (creator === null || !can(creator, "issue:create", projectResource(project))) {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    logger.warn("recurring issue paused: creator may no longer file issues", {
      orgId: rule.orgId,
      recurringIssueId: rule.id,
      createdBy: rule.createdBy,
    });
    return "paused";
  }

  const assigneeId =
    rule.assigneeId !== null &&
    (await resolveActor(rule.assigneeId, rule.orgId)) !== null
      ? rule.assigneeId
      : null;

  await createIssue(creator, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringIssueRepo.setLastOccurrence(rule.orgId, rule.id, occurrence);
  return "created";
}

